+        ),
+        throwsA(isA<ConfigException>()),
+      );
+    });
+  });
+
+  group('config — roles chain entries carry the tuning keys', () {
+    test('map-form chain entries parse the keys', () {
+      final doc =
+          loadYaml('''
+provider: openai
+model: glm-5.3-flash
+baseUrl: https://glm.example.com/v1
